#!/usr/bin/env python3
"""Read-only source review; synthetic temporary shell files only; no adb/CI/network."""
import itertools
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile

REPO = Path('/tmp/lifeguide-recovery-current')
EXPECTED_HEAD = '89a81432ebaa95f1d118595f87b90ef287f33693'

def head():
    return subprocess.run(['git', 'rev-parse', 'HEAD'], cwd=REPO,
                          capture_output=True, text=True, check=True).stdout.strip()

assert head() == EXPECTED_HEAD
sys.path.insert(0, str(REPO / 'apps/lifemate/tool'))
import test_personal_recovery_android as subject
from test_personal_recovery_android_test import RecoveryBoundaryTest

kinds = ('absent', 'empty', 'data', 'directory', 'fifo', 'symlink', 'dangling')
accepted = []
with tempfile.TemporaryDirectory(prefix='independent-cold-shell-') as root:
    base = Path(root)
    db = base / subject.DATABASE
    db.parent.mkdir()
    target = base / 'regular-target'
    target.write_bytes(b'')
    class Shell:
        def shell(self, *parts):
            return subprocess.run(['sh', '-c', parts[-1]], cwd=root,
                capture_output=True, text=True, check=True, timeout=2).stdout
    harness = subject.Harness.__new__(subject.Harness)
    harness.process_state = lambda package: 'ABSENT'
    harness.adb = Shell()
    harness._diagnose_cold_files = lambda package: None
    def create(path, kind):
        if kind == 'empty': path.write_bytes(b'')
        elif kind == 'data': path.write_bytes(b'x')
        elif kind == 'directory': path.mkdir()
        elif kind == 'fifo': os.mkfifo(path)
        elif kind == 'symlink': path.symlink_to(target)
        elif kind == 'dangling': path.symlink_to(base / 'missing-target')
    paths = [Path(str(db) + suffix) for suffix in ('-wal', '-shm', '-journal')]
    for kinds3 in itertools.product(kinds, repeat=3):
        for path, kind in zip(paths, kinds3): create(path, kind)
        valid = (kinds3 == ('absent', 'absent', 'absent') or
                 kinds3 == ('absent', 'absent', 'empty') or
                 (kinds3[0] == 'empty' and kinds3[1] in ('absent', 'empty', 'data')
                  and kinds3[2] == 'absent'))
        try:
            result = harness._cold(subject.ORIGINAL)
            accepted.append({'walShmJournal': kinds3, 'result': result})
            assert valid, (kinds3, result)
        except subject.AcceptanceError as error:
            assert str(error) == 'database_sidecar_present'
            assert not valid, kinds3
        for path in paths:
            if path.is_dir() and not path.is_symlink(): path.rmdir()
            elif path.exists() or path.is_symlink(): path.unlink()

case = RecoveryBoundaryTest()
case.setUp()
try:
    harness = case.make()
    harness.preflight()
    harness.install(subject.ORIGINAL)
    raw = subject.create_sample_database()
    for state in ('CLEAN', 'EMPTY_WAL', 'EMPTY_WAL_SHM'):
        case.adb.process, case.adb.sidecars = 'ABSENT', 'EMPTY_JOURNAL'
        def read(command, data=None):
            case.adb.sidecars = state
            return raw
        harness.binary = read
        try: harness.capture(subject.ORIGINAL)
        except subject.AcceptanceError as error:
            assert str(error) == 'database_cache_shape_changed'
        else: raise AssertionError('journal shape change accepted')
    case.adb.sidecars = 'EMPTY_JOURNAL'
    def restart(command, data=None):
        case.adb.process = 'PRESENT'
        return raw
    harness.binary = restart
    try: harness.capture(subject.ORIGINAL)
    except subject.AcceptanceError as error:
        assert str(error) == 'database_process_must_be_absent'
    else: raise AssertionError('process restart accepted')
finally:
    case.doCleanups()

commands = [
    ('focused', ['python3', '-m', 'unittest', 'discover', '-s', 'apps/lifemate/tool', '-p', '*personal_recovery*_test.py', '-v']),
    ('host', ['python3', '-m', 'unittest', 'discover', '-s', 'apps/lifemate/tool', '-p', '*_test.py', '-v']),
    ('b1', ['python3', '-m', 'unittest', 'discover', '-s', 'scripts/tests', '-p', 'test_recovery*.py', '-v']),
    ('whitespace', ['git', 'diff', '--check', 'c5942f4..HEAD']),
]
checks = []
for label, command in commands:
    result = subprocess.run(command, cwd=REPO, capture_output=True, text=True)
    log = Path('/tmp/lifeguide-cold-review-' + label + '.log')
    log.write_text(result.stdout + result.stderr)
    checks.append({'label': label, 'argv': command, 'exitCode': result.returncode, 'log': str(log)})
    assert result.returncode == 0, (label, str(log))
assert head() == EXPECTED_HEAD
print(json.dumps({'sourceCommit': EXPECTED_HEAD, 'matrix': {'cases': len(kinds) ** 3,
    'acceptedCombinations': accepted, 'unexpectedResults': 0},
    'captureChangeChecks': {'emptyJournalToOtherAcceptedShapes': 3, 'processRestart': 'REFUSED'},
    'checks': checks, 'result': 'PASS'}, indent=2))
